-- Objectflix seed data
-- Migration 0014: Add Inanimate Insanity Season 1 (2011-2012).
--
-- Adds the season row plus all 18 numbered episodes (+ the 5.5 interstitial
-- special), following the catalog title convention "<PREFIX> <num>: <Title>".
-- Episode ids continue after TPOT 24 (...077): this run uses ...078-...096.
-- Season id continues after BFDIE (...007): this season is ...008.
--
-- Idempotent by design: fixed UUIDs + INSERT OR IGNORE.
-- video_key is intentionally NULL: media is not uploaded to B2 yet, so
-- getMediaUrl() returns undefined and the frontend shows them as unreleased.

INSERT OR IGNORE INTO seasons (id, show_id, title, episode_count) VALUES
('20000000-0000-4000-8000-000000000008', '10000000-0000-4000-8000-000000000007', 'Inanimate Insanity (Season 1)', 19);

